def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate counts
    opp_c = 0
    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'D':
            my_d += 1

    # Recent window (last 12)
    w = 12 if n >= 12 else n
    w_opp_c = 0
    w_opp_d = 0
    w_dd = 0
    w_dc = 0
    start = n - w
    for i in range(start, n):
        a, b = history[i]
        if b == 'C':
            w_opp_c += 1
        else:
            w_opp_d += 1
        if a == 'D' and b == 'D':
            w_dd += 1
        if a == 'D' and b == 'C':
            w_dc += 1

    opp_prev = history[-1][1]
    my_prev = history[-1][0]

    # Adaptive cooperation threshold
    # Opponent's cooperation rate in whole match
    opp_rate = opp_c / n

    # Early game: cooperate to establish cooperation
    if n < 6:
        return 'C'

    # Detect always-defect / very high defection
    if opp_d >= n - 1 or (n >= 10 and opp_rate <= 0.15):
        # Mostly give up, but occasionally probe
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Detect always-cooperate: exploit gently while not destroying coop
    if opp_d == 0:
        # Late game exploit; mid game cooperate mostly with rare probes
        if n >= 85:
            return 'D'
        if n >= 25 and n % 9 == 0:
            return 'D'
        return 'C'

    # If we've defected a lot and opponent still cooperates, we may be over-exploiting
    # Back off to rebuild cooperation if opponent defection count is low
    if my_d >= 3 and opp_d <= 2 and opp_prev == 'C':
        return 'C'

    # Window-based adaptive ratios
    w_rate = w_opp_c / w
    # Recent defections by opponent
    w_def_rate = w_opp_d / w

    # If opponent is highly cooperative recently: exploit moderately
    if w_rate >= 0.85:
        # Probe sharply in late game
        if n >= 80:
            if n >= 95 or (opp_prev == 'C' and rng.random() < 0.55):
                return 'D'
            return 'C'
        # Occasional probe otherwise
        if n >= 25 and (n % 8 == 0 or rng.random() < 0.08):
            return 'D'
        return 'C'

    # If opponent recently defected a lot, punish
    if w_def_rate >= 0.6:
        # If we're both in DD spiral, occasionally break with C
        if my_prev == 'D' and opp_prev == 'D':
            if w_dc == 0 and w_dd >= 4:
                # death spiral; try to rebuild with some probability
                if rng.random() < 0.35:
                    return 'C'
        return 'D'

    # Opponent just defected
    if opp_prev == 'D':
        # If they've mostly cooperated overall, retaliate once then forgive
        if opp_rate >= 0.75:
            return 'D'
        # If recent cooperation is moderate, retaliate
        if w_rate >= 0.5:
            return 'D'
        # Heavy defection -> defect
        if w_rate < 0.3:
            return 'D'
        # Mixed: alternate retaliate/forgive
        if n >= 3 and history[-2][1] == 'D':
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated
    # Punish rare recent defections by us if they are being nice
    if my_prev == 'D':
        return 'C'

    # Late game: shift to exploitation when opponent is very cooperative
    remaining = 100 - n
    if remaining <= 5:
        if opp_rate >= 0.8:
            return 'D'
        if opp_prev == 'D':
            return 'D'
        return 'C'

    if remaining <= 12:
        if opp_rate >= 0.7 and w_rate >= 0.6:
            return 'D'
        if opp_rate < 0.4:
            return 'D'
        return 'C'

    # Mid-game: if opponent has been cooperative and we have cooperated, keep C
    # but occasionally test
    if opp_rate >= 0.65 and w_rate >= 0.6:
        if n >= 30 and n % 10 == 0:
            return 'D'
        return 'C'

    # Tit-for-tat core with forgiveness for isolated defections
    if opp_rate >= 0.4:
        # Forgiving TFT
        if w_opp_d == 1 and w_opp_c >= 4:
            return 'C'
        return 'C'

    # Default: defect against unreliable opponent
    return 'D'
